steps.instruction:
Author the rule with sourced values. Example shape inside a matching family/revision block:

  prompt-cache-lifetime {
      short 300
      long 3600
  }

Write the numbers UNQUOTED — KDL parses `300` as a number and `"300"` as a string, and the resolved type demands a number. Use `short`/`long` as child names (lowercase, no dashes, so `payloadKey()` passes them through untouched). You may declare only one tier in a given block; the payload is genuinely partial. Every value needs a source comment naming the provider doc, matching the file's existing convention (see the AWS model-card comment at :252-254).

code_shape:
// packages/catalog/src/types.ts — placed just above `export interface AnthropicCompat` (:526)
export type CacheRetentionTier = "short" | "long";

/**
 * Per-tier prompt-cache entry lifetime, in SECONDS.
 * An absent key means that tier's lifetime is unknown — consumers must fail safe
 * and must not substitute a default. Rule-owned via the `prompt-cache-lifetime`
 * KDL axis; never derived from a model-id string match in TypeScript.
 */
export type PromptCacheLifetime = Partial<Record<CacheRetentionTier, number>>;

export interface AnthropicCompat {
  // …existing fields…
  /** Per-tier prompt-cache entry lifetime in seconds. Unset when unknown. */
  promptCacheLifetime?: PromptCacheLifetime;
}

// packages/catalog/src/types.ts:963 — the Omit list is what keeps the field optional.
export type ResolvedAnthropicCompat = Required<Omit<AnthropicCompat,
  "streamIdleTimeoutMs" | "thinkingLoopGuard" | "promptCacheLifetime">> & {
  thinkingLoopGuard?: AnthropicCompat["thinkingLoopGuard"];
  streamIdleTimeoutMs?: number;
  /** Unset when unknown; consumers fail safe. */
  promptCacheLifetime?: PromptCacheLifetime;
  officialEndpoint: boolean;
  firstPartyProvider: boolean;
};

// packages/catalog/src/compat/axes.ts — beside the bedrock prompt-cache axes (:216-218)
"prompt-cache-lifetime": wire("promptCacheLifetime", ["anthropic", "bedrock"], "object"),

// packages/catalog/src/compat/rules/classes/anthropic.kdl — unquoted integer seconds
on "anthropic" {
  family "opus" {
    revision "=4.5" {
      // <source: provider cache-retention doc>
      prompt-cache-lifetime {
        short 300
        long 3600
      }
    }
  }
}
